// Извлекаем и очищаем текст из PDF структуры
function extractTextFromPDF(pdfData) {
  let text = pdfData.text || '';

  // Минимальная очистка текста от артефактов OCR
  text = text
    // Убираем только явные множественные пробелы (2 и более)
    .replace(/  +/g, ' ')
    // Убираем пробелы в начале и конце строк
    .replace(/^\s+|\s+$/gm, '')
    // Объединяем разорванные строки только если они явно разорваны (строка заканчивается буквой, а следующая начинается с маленькой)
    .replace(/([а-яё])\n([а-яё])/g, '$1 $2')
    // Убираем избыточные переносы строк (3 и более)
    .replace(/\n{3,}/g, '\n\n')
    // Убираем пробелы в начале и конце всего текста
    .trim();

  return text;
}

// Извлекаем метаданные из PDF
function extractPDFMetadata(pdfData) {
  const info = pdfData.info || {};
  const metadata = pdfData.metadata || {};

  return {
    totalPages: pdfData.numpages || 0,
    renderedPages: pdfData.numrender || 0,
    producer: info.Producer || metadata['pdf:producer'] || 'Unknown',
    creationDate: info.CreationDate || null,
    modificationDate: info.ModDate || null,
    format: metadata['dc:format'] || 'application/pdf',
    documentId: metadata['xapmm:documentid'] || null
  };
}

// Функция для разбивки текста на chunks
function chunkText(text, maxTokens = 6000) {
  // Приблизительно 1 токен = 0.75 слова для русского языка
  const maxWords = Math.floor(maxTokens * 0.75);
  const words = text.split(/\s+/);
  const chunks = [];

  let currentChunk = [];
  let currentWordCount = 0;

  for (const word of words) {
    // Если добавление слова превысит лимит, сохраняем текущий chunk
    if (currentWordCount + 1 > maxWords && currentChunk.length > 0) {
      chunks.push(currentChunk.join(' '));
      currentChunk = [word];
      currentWordCount = 1;
    } else {
      currentChunk.push(word);
      currentWordCount++;
    }
  }

  // Добавляем последний chunk если он не пустой
  if (currentChunk.length > 0) {
    chunks.push(currentChunk.join(' '));
  }

  return chunks;
}

// Функция для подсчета приблизительного количества токенов
function estimateTokenCount(text) {
  // Приблизительная оценка: 1 токен ≈ 0.75 слова для русского языка
  const words = text.split(/\s+/).length;
  return Math.ceil(words / 0.75);
}

// Основная логика
const pdfData = $input.all()[0].json;
const fullText = extractTextFromPDF(pdfData);
const metadata = extractPDFMetadata(pdfData);

// Проверяем, что текст был извлечен
if (!fullText || fullText.length === 0) {
  throw new Error('Не удалось извлечь текст из PDF файла');
}

console.log(`Извлечено ${fullText.length} символов из PDF (${metadata.totalPages} страниц)`);

// Разбиваем на chunks
const chunks = chunkText(fullText, 6000); // Оставляем запас для промпта и ответа

// Создаем результат
const result = chunks.map((chunk, index) => ({
  chunkIndex: index + 1,
  totalChunks: chunks.length,
  text: chunk,
  estimatedTokens: estimateTokenCount(chunk),
  wordCount: chunk.split(/\s+/).length,
  characterCount: chunk.length,
  // PDF метаданные
  sourceType: 'PDF',
  documentId: metadata.documentId || $json.documentId || 'unknown',
  documentTitle: $json.documentTitle || `PDF Document (${metadata.totalPages} pages)`,
  totalPages: metadata.totalPages,
  producer: metadata.producer,
  creationDate: metadata.creationDate,
  // Дополнительная информация для отладки
  originalTextLength: fullText.length,
  compressionRatio: Math.round((chunk.length / fullText.length) * 100)
}));

console.log(`Создано ${result.length} фрагментов текста`);

return result;
